            int cmp = metric.apply(i).compareTo(metric.apply(best));
            if (cmp > 0 || (cmp == 0 && tieBreaker.compare(items.get(i), items.get(best)) < 0)) {
                best = i;
            }
        }
        return best;
    }
}

